    var ko = (window.EXO_BIAYA ? EXO_BIAYA.pengaturan() : null); if (ko && ko.ongkir.aktif) h += '<div class="card elev-sm gap-6"><div class="f-head t-15">Program Gratis Ongkir</div><div class="t-115 o-7 lh-15">Pembeli dapat subsidi ongkir sampai ' + rp(ko.ongkir.maks) + ' untuk belanja ≥ ' + rp(ko.ongkir.min) + ' di toko peserta' + (ko.ongkir.hanyaPeserta ? '' : ' (saat ini berlaku untuk semua toko)') + '. Peserta dikenai tambahan biaya layanan ' + ko.komisi.programOngkir + '% per pesanan.</div><button class="' + kelas('pill pill-sm', !!t.programOngkir) + '"' + aksi('tprogramOngkir') + '>' + (t.programOngkir ? '✓ Toko ini peserta' : 'Ikut program') + '</button></div>';
