  K.tpengaturan = K.tpengaturan || {};
  A.tprogramOngkir = function () { var t = tokoSaya(); if (!t) return; window.EXO_DB.update('toko', t.id, { programOngkir:!t.programOngkir }); X.sekilas(t.programOngkir ? 'Keluar dari program Gratis Ongkir.' : 'Toko terdaftar di program Gratis Ongkir.'); };
  A.tkurirToggle = function (k) { var t = tokoSaya(), kr = (t.kurir || []).slice(), i = kr.indexOf(k); if (i >= 0) kr.splice(i, 1); else kr.push(k); if (!kr.length) { X.sekilas('Minimal satu kurir.', 'err'); return; } T().simpanPengaturan(t.id, { kurir:kr }); };
  A.ttemplateTambah = function () { var teks = window.prompt('Template balasan:'); if (!teks) return; var t = tokoSaya(); T().simpanPengaturan(t.id, { templateBalasan:(t.templateBalasan || []).concat([teks]) }); };
  A.ttemplateHapus = function (i) { var t = tokoSaya(), tp = (t.templateBalasan || []).slice(); tp.splice(+i, 1); T().simpanPengaturan(t.id, { templateBalasan:tp }); };
  A.tpengaturanSimpan = function () { var t = tokoSaya(), f = K.tpengaturan, patch = {}; ['nama','deskripsi','kota','jamBuka','catatan','alamat','kodePos','telp'].forEach(function (k) { if (f[k] != null && String(f[k]).trim()) patch[k] = String(f[k]).trim(); }); T().simpanPengaturan(t.id, patch); K.tpengaturan = {}; X.sekilas('Pengaturan toko tersimpan.'); };
